/// <summary>
/// Method to set the Category Hierarchy Name based on the Agreement Header's Default Agreement Line Type
/// </summary>
public static METEcoResCategoryHierarchyName metSetCategoryHierarchyName(SalesAgreementHeader  _salesAgreementHeader)
{
    EcoResCategoryHierarchy ecoResCategoryHierarchy;
    EcoResCategoryHierarchyRole ecoResCategoryHierarchyRole;
    METEcoResCategoryHierarchyName  metEcoResCategoryHierarchyName;
    AgreementLine        agreementLine;

    SalesAgreementHeader    salesAgreementHeader = _salesAgreementHeader;

    if (salesAgreementHeader.CustAccount == '')
    {
        return '';
    }

    //Product Value Commitment OR Product category value commitment 
    if (salesAgreementHeader.DefaultAgreementLineType == CommitmentType::ProductRootCategory || salesAgreementHeader.DefaultAgreementLineType == CommitmentType::ProductCategory)
    {
        select firstonly1 ecoResCategoryHierarchy
            exists join ecoResCategoryHierarchyRole
                where ecoResCategoryHierarchyRole.CategoryHierarchy == ecoResCategoryHierarchy.RecId
                && ecoResCategoryHierarchyRole.NamedCategoryHierarchyRole == EcoResCategoryNamedHierarchyRole::Sales;

        metEcoResCategoryHierarchyName = ecoResCategoryHierarchy.Name;
    }
    //Vendor category value commitment
    else if (salesAgreementHeader.DefaultAgreementLineType == CommitmentType::METVendorCategoryProductVolume)
    {
        select firstonly1 ecoResCategoryHierarchy
            exists join ecoResCategoryHierarchyRole
                where ecoResCategoryHierarchyRole.CategoryHierarchy == ecoResCategoryHierarchy.RecId
            && ecoResCategoryHierarchyRole.NamedCategoryHierarchyRole == EcoResCategoryNamedHierarchyRole::RetailSpecialGroup;

        metEcoResCategoryHierarchyName = ecoResCategoryHierarchy.Name;
    }

    return metEcoResCategoryHierarchyName;;
}

/// <summary>
/// Insert method override to set the Category Hierarchy Name on insert of Agreement Line
/// </summary>
public void insert()
{
    this.METCategoryHierarchyName = AgreementLine::metSetCategoryHierarchyName(this.agreementHeader());

    next insert();
}
